// The bench of the output check on the generated images (AI-A1, devil C73).
//
// C73: "Generated bytes pass a safety check before they are stored or sent;
// flagged output is discarded." The check runs in the AI service, in-process,
// between the answer of the engine and the upload of the bridge. This bench
// measures the candidate in exactly that shape: one Node process, the CPU, the
// model on the disk of the volume.
//
// The model is local and the run has no network at all: env.allowRemoteModels
// is false and env.localModelPath points at the volume, so a request to the
// hub is an error, not a download.
//
// usage: node nsfw-bench.mjs --models <dir> --model <id> --dtype fp32|q8
//                              --manifest <tsv> --out <scores.tsv>
//                              [--label <name>] [--warmup 3] [--concurrency 4]
//
// The manifest is a TSV: the set, the id of the image, the path of the file.
// The scores are written as a TSV: the set, the id, the score of the unsafe
// label, the milliseconds of the whole chain (read, decode, preprocess,
// inference). No image and no prompt is ever written.

import { readFileSync, writeFileSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { env, pipeline, RawImage } from '@huggingface/transformers';

const options = { warmup: 3, concurrency: 4, label: 'run' };
const argv = process.argv.slice(2);
for (let index = 0; index < argv.length; index += 1) {
	const arg = argv[index];
	if (!arg.startsWith('--')) continue;
	const [key, inline] = arg.replace(/^--/, '').split('=');
	let value = inline;
	if (value === undefined) {
		value = argv[index + 1] ?? 'true';
		index += 1;
	}
	options[key] = value;
}
for (const key of ['models', 'model', 'dtype', 'manifest', 'out']) {
	if (!options[key]) {
		console.error(`missing --${key}`);
		process.exit(2);
	}
}
const warmup = Number(options.warmup);
const concurrency = Number(options.concurrency);

// --- the model is local, and only local --------------------------------------
env.allowRemoteModels = false;
env.allowLocalModels = true;
env.localModelPath = options.models;

// --- the helpers -------------------------------------------------------------
/** The percentile of a sorted list, by linear interpolation (the way of numpy). */
function percentile(sorted, quantile) {
	if (sorted.length === 0) return null;
	const at = (sorted.length - 1) * quantile;
	const low = Math.floor(at);
	const high = Math.ceil(at);
	if (low === high) return sorted[low];
	return sorted[low] + (sorted[high] - sorted[low]) * (at - low);
}

function stats(values) {
	if (values.length === 0) return null;
	const sorted = [...values].sort((a, b) => a - b);
	const sum = sorted.reduce((total, value) => total + value, 0);
	return {
		n: sorted.length,
		min: sorted[0],
		p50: percentile(sorted, 0.5),
		p95: percentile(sorted, 0.95),
		max: sorted[sorted.length - 1],
		mean: sum / sorted.length,
	};
}

const round = (value, digits = 1) =>
	value === null || value === undefined ? null : Number(value.toFixed(digits));

function rssMb() {
	return round(process.memoryUsage().rss / (1024 * 1024), 1);
}

// --- the fail-closed mode ----------------------------------------------------
// The model file is not there: the check has to refuse, and the time to the
// refusal is what the service waits before it can say "no".
if (options['fail-closed']) {
	const start = performance.now();
	try {
		await pipeline('image-classification', options.model, {
			dtype: options.dtype,
			device: 'cpu',
		});
		console.log('fail_closed_ms -1 (the model loaded, nothing failed)');
	} catch (error) {
		console.log(`fail_closed_ms ${(performance.now() - start).toFixed(1)}`);
		console.log(`fail_closed_error ${String(error.message).slice(0, 300)}`);
	}
	process.exit(0);
}

// --- the manifest ------------------------------------------------------------
const rows = readFileSync(options.manifest, 'utf8')
	.split('\n')
	.filter((line) => line.trim() !== '')
	.map((line) => {
		const [set, id, path] = line.split('\t');
		return { set, id, path };
	});

console.log(`label ${options.label}`);
console.log(`dtype ${options.dtype}`);
console.log(`model ${options.model}`);
console.log(`localModelPath ${env.localModelPath}`);
console.log(`allowRemoteModels ${env.allowRemoteModels}`);
console.log(`manifest ${options.manifest}`);
console.log(`images ${rows.length}`);
console.log(`node ${process.version}`);
console.log(`platform ${process.platform} ${process.arch}`);
console.log(`uptime_s ${(Number(readFileSync('/proc/uptime', 'utf8').split(' ')[0])).toFixed(1)}`);

// --- the load ----------------------------------------------------------------
const loadStart = performance.now();
const classifier = await pipeline('image-classification', options.model, {
	dtype: options.dtype,
	device: 'cpu',
});
const loadMs = performance.now() - loadStart;
console.log(`load_ms ${loadMs.toFixed(1)}`);
console.log(`rss_after_load_mb ${rssMb()}`);

// --- the warm-up -------------------------------------------------------------
// The first call pays for the lazy init of the session of ONNX: it is not the
// latency of the slice, it is the latency of the first image of the process.
for (const row of rows.slice(0, warmup)) {
	const image = await RawImage.read(new Blob([readFileSync(row.path)]));
	await classifier(image);
}
console.log(`warmup_images ${Math.min(warmup, rows.length)}`);

// --- the pass, one image at a time -------------------------------------------
const scores = [];
const decodeTimes = [];
const inferTimes = [];
for (const row of rows) {
	const bytes = readFileSync(row.path);
	const decodeStart = performance.now();
	const image = await RawImage.read(new Blob([bytes]));
	const decodeMs = performance.now() - decodeStart;
	const inferStart = performance.now();
	const answer = await classifier(image);
	const inferMs = performance.now() - inferStart;
	const unsafe = answer.find((entry) => entry.label === 'nsfw');
	if (!unsafe) {
		console.error(`no nsfw label for ${row.id}`);
		process.exit(3);
	}
	decodeTimes.push(decodeMs);
	inferTimes.push(inferMs);
	scores.push({
		set: row.set,
		id: row.id,
		score: unsafe.score,
		ms: decodeMs + inferMs,
	});
}
console.log(`sequential_ms ${JSON.stringify(stats(scores.map((row) => row.ms)))}`);
console.log(`decode_ms ${JSON.stringify(stats(decodeTimes))}`);
console.log(`infer_ms ${JSON.stringify(stats(inferTimes))}`);

// --- the pass, four images at a time -----------------------------------------
// The slice would answer four requests at once: the promise of the four
// images is one, and the time of every image is its own.
const concurrent = [];
for (let index = 0; index < rows.length; index += concurrency) {
	const batch = rows.slice(index, index + concurrency);
	const timed = await Promise.all(
		batch.map(async (row) => {
			const start = performance.now();
			const bytes = readFileSync(row.path);
			const image = await RawImage.read(new Blob([bytes]));
			const answer = await classifier(image);
			return { id: row.id, ms: performance.now() - start };
		}),
	);
	for (const entry of timed) concurrent.push(entry.ms);
}
console.log(`concurrent_ms ${JSON.stringify(stats(concurrent))}`);
console.log(`rss_after_run_mb ${rssMb()}`);

// --- the scores --------------------------------------------------------------
const out = ['set\tid\tscore\tms'];
for (const row of scores) {
	out.push(`${row.set}\t${row.id}\t${row.score.toFixed(6)}\t${row.ms.toFixed(1)}`);
}
writeFileSync(options.out, `${out.join('\n')}\n`);
console.log(`scores ${scores.length}`);
console.log(`out ${options.out}`);
